### posApi.ts — createApi Root

```
const posApi = createApi({
  reducerPath: 'posApi',
  baseQuery: posBaseQuery,     // Routes all requests through PosRequestSender
  tagTypes: ['Table', 'Order', 'Payment', 'Sync', 'System', 'Config'],
  endpoints: () => ({})        // Empty — injected per domain via injectEndpoints
})
```

`posBaseQuery` takes a `BridgeArg` interface and calls `PosRequestSender.sendRequest()`:
```
interface BridgeArg {
  cmd: string            // 'TABLE:GET_ALL', 'ORDER:ADD_ITEM', etc.
  params: Record<string, unknown>
  idempotencyKey?: string
}
```

### tableApi.ts — Table Domain Endpoints

```
tableApi.injectEndpoints({
  endpoints: (build) => ({
    getTables: build.query<TableData, void>({
      query: () => ({ cmd: 'TABLE:GET_ALL', params: {} }),
      providesTags: ['Table']
    }),
    selectTable: build.mutation<unknown, { id: number }>({
      query: ({ id }) => ({ cmd: 'TABLE:SELECT', params: { id } }),
      invalidatesTags: ['Table']
    })
  })
})

interface TableData {
  tables: Array<{
    id: number
    name: string
    label: string
    status: 'E' | 'U' | 'L'  // Empty, Used(Occupied), Locked
    floor: number
  }>
}
```

### orderApi.ts — Order/Menu Domain

```
getMenu: query<MenuData, void>
  → cmd: 'MENU:GET_ALL'
  → providesTags: ['Order']

getOrder: query<OrderData, { tableId }>
  → cmd: 'ORDER:GET'
  → providesTags: ['Order']

addOrderItem: mutation<unknown, { tableId, menuId, quantity }>
  → cmd: 'ORDER:ADD_ITEM'
  → invalidatesTags: ['Order', 'Table']

interface MenuData {
  categories: Array<{ id, name, sort }>
  items: Array<{ id, name, price, categoryId, ... }>
}
```

### Hook Usage Example

```
// Auto-load data on screen entry
const { data, isLoading } = useGetTablesQuery()

// Execute mutation on user action
const [selectTable] = useSelectTableMutation()
await selectTable({ id: 5 })
// → invalidatesTags: ['Table'] → useGetTablesQuery auto-refetch
```

